import Head from 'next/head';
import fetch from 'isomorphic-unfetch';
import WooCommerceConfig from '../services/woocommerce/config_woocommerce';

function Index({ data }) {

    return (
        <div className="container">
            <Head>
                <title>Create Next App</title>
                <link rel="icon" href="/favicon.ico" />
            </Head>


            <main>
                {console.log("ss", data)}
            </main>

        </div>

    );
}



Index.getInitialProps = async () => {
    WooCommerce.getAsync('products').then(function (data) {
        return { data };
    });
    // return { data }
}

export default Index;
